    private static void SetCaption(Label label, string text)
    {
        label.AutoSize = true;
        label.ForeColor = Color.FromArgb(0xA1, 0xA1, 0xAA);
        label.Margin = new Padding(0, 8, 0, 2);
        label.Text = text;
    }

    private static void SetupMoney(NumericUpDown box)
    {
        box.BackColor = Color.FromArgb(0x25, 0x20, 0x38);
        box.DecimalPlaces = 2;
        box.Dock = DockStyle.Fill;
        box.ForeColor = Color.FromArgb(0xF5, 0xF5, 0xF7);
        box.Maximum = new decimal([10_000_000, 0, 0, 0]);
        box.MinimumSize = new Size(180, 32);
        box.ThousandsSeparator = true;
    }

    private static void SetupInt(NumericUpDown box)
    {
        box.BackColor = Color.FromArgb(0x25, 0x20, 0x38);
        box.DecimalPlaces = 0;
        box.Dock = DockStyle.Fill;
        box.ForeColor = Color.FromArgb(0xF5, 0xF5, 0xF7);
        box.Maximum = new decimal([1_000_000, 0, 0, 0]);
        box.MinimumSize = new Size(180, 32);
    }

